-- Care Salon original logo only; preserve loyalty, catalog, customers and subscriptions
BEGIN;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='60s';
CREATE TEMP TABLE care_logo_before ON COMMIT DROP AS SELECT jsonb_build_object('cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.cafes t),'subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.subscriptions t),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.loyalty_cards t),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.menu_products t),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.menu_categories t),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.offers t),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.brand_feature_overrides t),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.cafe_loyalty_programs t),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.cafe_loyalty_experience t),'other_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'294d1c16-83d9-436f-bfc7-982e4a98f754'),'other_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'294d1c16-83d9-436f-bfc7-982e4a98f754')) snapshot;
CREATE TEMP TABLE care_logo_settings_before ON COMMIT DROP AS SELECT to_jsonb(s)-'logo_storage_path'-'updated_at' payload FROM public.cafe_settings s WHERE cafe_id='294d1c16-83d9-436f-bfc7-982e4a98f754';
DO $guard$ BEGIN PERFORM 1 FROM public.cafes WHERE id='294d1c16-83d9-436f-bfc7-982e4a98f754' AND slug='brand-04cb352c9f44' AND status='active' AND is_public AND business_category='hair_salons' AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Care account identity changed';END IF;
IF NOT EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='294d1c16-83d9-436f-bfc7-982e4a98f754') OR EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='294d1c16-83d9-436f-bfc7-982e4a98f754' AND (logo_url IS NOT NULL OR (logo_storage_path IS NOT NULL AND logo_storage_path<>'294d1c16-83d9-436f-bfc7-982e4a98f754/identity/care-20261104-8e2eac943fa6d0da.webp'))) OR EXISTS(SELECT 1 FROM public.cafe_custom_identity WHERE cafe_id='294d1c16-83d9-436f-bfc7-982e4a98f754' AND (logo_url IS NOT NULL OR logo_storage_path IS DISTINCT FROM '294d1c16-83d9-436f-bfc7-982e4a98f754/identity/care-20261104-8e2eac943fa6d0da.webp' OR palette IS DISTINCT FROM '{"primary":"#29221C","secondary":"#F2E5CB","accent":"#A52E2E","background":"#FFF8EA","text":"#29221C","button":"#A52E2E"}'::jsonb)) THEN RAISE EXCEPTION 'Owner identity changed; preserve';END IF;END $guard$;
UPDATE public.cafe_settings SET logo_storage_path='294d1c16-83d9-436f-bfc7-982e4a98f754/identity/care-20261104-8e2eac943fa6d0da.webp',updated_at=now() WHERE cafe_id='294d1c16-83d9-436f-bfc7-982e4a98f754' AND logo_storage_path IS DISTINCT FROM '294d1c16-83d9-436f-bfc7-982e4a98f754/identity/care-20261104-8e2eac943fa6d0da.webp';
INSERT INTO public.cafe_custom_identity(cafe_id,logo_storage_path,logo_url,palette) VALUES('294d1c16-83d9-436f-bfc7-982e4a98f754','294d1c16-83d9-436f-bfc7-982e4a98f754/identity/care-20261104-8e2eac943fa6d0da.webp',NULL,'{"primary":"#29221C","secondary":"#F2E5CB","accent":"#A52E2E","background":"#FFF8EA","text":"#29221C","button":"#A52E2E"}'::jsonb) ON CONFLICT(cafe_id) DO NOTHING;
DO $verify$ DECLARE actual jsonb;BEGIN SELECT jsonb_build_object('cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.cafes t),'subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.subscriptions t),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.loyalty_cards t),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.menu_products t),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.menu_categories t),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.offers t),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.brand_feature_overrides t),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.cafe_loyalty_programs t),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text)::text,'')) FROM public.cafe_loyalty_experience t),'other_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'294d1c16-83d9-436f-bfc7-982e4a98f754'),'other_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'294d1c16-83d9-436f-bfc7-982e4a98f754')) INTO actual;IF actual IS DISTINCT FROM(SELECT snapshot FROM care_logo_before) THEN RAISE EXCEPTION 'Protected data changed';END IF;IF (SELECT to_jsonb(s)-'logo_storage_path'-'updated_at' FROM public.cafe_settings s WHERE cafe_id='294d1c16-83d9-436f-bfc7-982e4a98f754') IS DISTINCT FROM(SELECT payload FROM care_logo_settings_before) THEN RAISE EXCEPTION 'Other settings changed';END IF;END $verify$;
COMMIT;
